create table auditoria (data_hora timestamp(6) with time zone not null, id bigint generated by default as identity, acao varchar(255) not null, modulo varchar(255) not null, origem varchar(255), registro varchar(255), usuario varchar(255) not null, primary key (id));
create table clientes (data_nascimento date, estado varchar(2), revisado boolean not null, id bigint generated by default as identity, revisao bigint not null, cep varchar(9), numero varchar(10), cpf varchar(14), orgao_expedidor varchar(20), rg varchar(20), telefone varchar(20), email varchar(150), bairro varchar(255), cidade varchar(255), endereco varchar(255), filiacao varchar(255), nome varchar(255) not null, primary key (id), constraint uk_cliente_cpf unique (cpf));
create table configuracoes (id bigint generated by default as identity, chave varchar(255) not null unique, valor TEXT, primary key (id));
create table documentos (cliente_id bigint not null, data_upload timestamp(6) not null, id bigint generated by default as identity, tamanho_arquivo bigint not null, caminho_arquivo varchar(255) not null, nome_armazenado varchar(255) not null, nome_original varchar(255) not null, tipo_arquivo varchar(255) not null, primary key (id));
create table minutas (cliente_id bigint not null, criado_em timestamp(6) with time zone, id bigint generated by default as identity, modelo_versao_id bigint not null, revisado_em timestamp(6) with time zone, revisao bigint not null, autor varchar(255), conteudo TEXT not null, revisor varchar(255), status varchar(255), primary key (id));
create table modelo_versoes (numero integer not null, criado_em timestamp(6) with time zone, id bigint generated by default as identity, modelo_id bigint not null, autor varchar(255), conteudo TEXT not null, primary key (id), unique (modelo_id, numero));
create table modelos (numero_versao integer not null, atualizado_em timestamp(6) with time zone, id bigint generated by default as identity, revisao bigint not null, area varchar(255), autor varchar(255), categoria varchar(255), codigo varchar(255) not null unique, conteudo TEXT not null, descricao varchar(255), nome varchar(255) not null, status varchar(255) not null, tags varchar(255), primary key (id));
create table resultados_ocr (data_processamento timestamp(6) not null, documento_id bigint not null unique, id bigint generated by default as identity, revisao bigint not null, resultado_json TEXT, status varchar(255) not null, primary key (id));
create table sessoes (expira_em timestamp(6) with time zone not null, id bigint generated by default as identity, usuario_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table usuarios (ativo boolean not null, id bigint generated by default as identity, email varchar(255) not null unique, nome varchar(255) not null, oab varchar(255), perfil varchar(255) not null, senha_hash varchar(255) not null, primary key (id));
create index idx_sessoes_expira_em on sessoes (expira_em);
alter table if exists documentos add constraint FKnokfh9y0gk86f0nd7quy3b0gp foreign key (cliente_id) references clientes;
alter table if exists minutas add constraint FKj7cflq72tl3px88klutgp0h8 foreign key (cliente_id) references clientes;
alter table if exists minutas add constraint FKgaqlh8os50kqcafgfr031ngbq foreign key (modelo_versao_id) references modelo_versoes;
alter table if exists modelo_versoes add constraint FKbtiolw630s48e5jgdju9ssh8o foreign key (modelo_id) references modelos;
alter table if exists resultados_ocr add constraint FK3rng6hgecjr1mjgci8p9u53s8 foreign key (documento_id) references documentos;
alter table if exists sessoes add constraint FK94oumc096illook3hms99wqqa foreign key (usuario_id) references usuarios;
